% maya_lc_to_jdn.m — Long Count (baktun katun tun winal kin) -> JDN (GMT 584283)
% Uso: jdn = maya_lc_to_jdn(13,0,0,0,0)  % -> 2456283
function jdn = maya_lc_to_jdn(b, k, t, w, n)
  if nargin ~= 5
    error('maya_lc_to_jdn: se requieren 5 digitos (b k t w n)');
  end
  pesos = [144000, 7200, 360, 20, 1];
  digs = [b, k, t, w, n];
  jdn = 584283 + sum(digs .* pesos);
end

% tonalpohualli.m — dia n (1-based) del ciclo 260 -> [numero 1-13, signo 1-20]
% Uso: [num, signo] = tonalpohualli(1)  % -> 1 Cipactli (1,1)
function [num, signo] = tonalpohualli(n)
  if nargin ~= 1 || n < 1 || floor(n) ~= n
    error('tonalpohualli: n debe ser entero >= 1');
  end
  num = mod(n - 1, 13) + 1;
  signo = mod(n - 1, 20) + 1;
end

% run_all.m — verificacion completa del experimento (medido, determinista)
% Uso desde el directorio experiment/: octave --quiet run_all.m
