assert(persa_bisiesto(1404) == 0 && persa_bisiesto(1405) == 0);
disp('persa 1403 leap / 1404-1405 comunes OK');

disp('== M4 metricas ==');
T = 365.24219;
fprintf('anio medio persa-33 : %.8f (err %+.2f s/anio)\n', 12053/33, (12053/33 - T) * 86400);
fprintf('anio medio gregoriano: %.6f (err %+.2f s/anio)\n', 365.2425, (365.2425 - T) * 86400);
fprintf('anio medio juliano   : %.6f (err %+.2f s/anio)\n', 365.25, (365.25 - T) * 86400);
fprintf('Haab 365 exacto      : err %+.2f s/anio\n', (365 - T) * 86400);
fprintf('deriva Haab/Rueda 52a: %.3f dias\n', 52 * (T - 365));
fprintf('era 13 baktunes      : %.2f anios tropicos\n', 1872000 / T);
disp('== TODO MEDIDO OK ==');

% persa_bisiesto.m — aproximacion ciclo-33 (Borkowski/jalcal): restos {1,5,9,13,17,22,26,30} mod 33
% NOTA: la regla real es astronomica (equinoccio Teheran); el ciclo-33 es aproximacion
% documentada con rupturas de 29 anios. Uso: persa_bisiesto(1404) % -> 0 (comun)
function leap = persa_bisiesto(y)
  if nargin ~= 1 || floor(y) ~= y
    error('persa_bisiesto: y debe ser anio jalali entero');
  end
  r = mod(y, 33);
  leap = any(r == [1, 5, 9, 13, 17, 22, 26, 30]);
end

"""model.py — funciones calendáricas puras (réplica exacta de los .m de Octave)."""
from math import gcd
from .data import GMT_JDN_ZERO, PERSIAN_RESIDUES_MOD33

LC_WEIGHTS = (144000, 7200, 360, 20, 1)

def lcm(a, b):
    return a // gcd(a, b) * b

def maya_lc_to_jdn(b, k, t, w, n):
    return GMT_JDN_ZERO + (b * 144000 + k * 7200 + t * 360 + w * 20 + n)

def tonalpohualli(n):
    assert isinstance(n, int) and n >= 1
    return ((n - 1) % 13 + 1, (n - 1) % 20 + 1)

def persa_bisiesto(y):
    """Aproximación ciclo-33 (ver persa_bisiesto.m para la salvedad astronómica)."""
    return (y % 33) in PERSIAN_RESIDUES_MOD33

def mean_year_error_s(mean_year, tropical=365.24219):
    return (mean_year - tropical) * 86400.0

function result = ternary_codec(data, mode)
% TERNARY_CODEC  Codificador/descodificador ternario balanceado
%   result = ternary_codec(data, 'encode') — convierte valores a trits
%   result = ternary_codec(data, 'decode') — convierte trits a valores
%
%   Inspiración: aritmética ternaria rusa (Setun, 1958)
%   Trits: -1 (frío/bajo), 0 (normal), +1 (caliente/alto)

  if nargin < 2
    mode = 'encode';
  end

  if strcmp(mode, 'encode')
    % Clasificar en 3 estados: -1, 0, +1
    % Umbrales: < 20°C = -1, 20-25°C = 0, > 25°C = +1
    trits = zeros(size(data));
    trits(data < 20) = -1;
    trits(data >= 20 & data <= 25) = 0;
    trits(data > 25) = 1;

    % Convertir secuencia de trits a número ternario balanceado
    % El número decimal equivalente
    n_trits = length(trits);
    decimal_val = 0;
    for i = 1:n_trits
      decimal_val = decimal_val + trits(i) * 3^(n_trits - i);
    end

    result.trits = trits;
    result.n_trits = n_trits;
    result.decimal = decimal_val;
    result.n_symbols = n_trits;

  elseif strcmp(mode, 'decode')
    % Descodificar número decimal a trits balanceados
    decimal_val = data;
    if decimal_val == 0
      trits = [0];
    else
      n = ceil(log(abs(decimal_val) + 1) / log(3));
      trits = zeros(1, n);
      remaining = decimal_val;
      for i = n:-1:1
        trit = mod(remaining + 1, 3) - 1;
        trits(i) = trit;
        remaining = (remaining - trit) / 3;
      end
    end

    result.trits = trits;
    result.n_trits = length(trits);
    result.decimal = decimal_val;

  else
    error('Modo desconocido: use encode o decode');
  end

end

function result = residual_compressor(trits, block_size)
% RESIDUAL_COMPRESSOR  Compresión por residuos mod-33
%   result = residual_compressor(trits) — detecta ciclos usando mod-33
%   Inspiración: ciclo persa de 33 años (calendario perpetuo)
%
%   Método:
%   1. Dividir secuencia de trits en bloques de 4
%   2. Calcular residuo mod-33 de cada bloque
%   3. Detectar repeticiones de residuos (= patrones cíclicos)
%   4. Comprimir secuencias con run-length encoding ternario

  if nargin < 2
    block_size = 4;
  end

  n_trits = length(trits);
  n_blocks = floor(n_trits / block_size);

  if n_blocks == 0
    result.compressed = trits;
    result.residues = [];
    result.cycles_detected = 0;
    result.compression_ratio = 1.0;
    return;
  end

  % Calcular residuos mod-33 de cada bloque
  residues = zeros(1, n_blocks);
  for i = 1:n_blocks
    block = trits((i-1)*block_size + 1 : i*block_size);
    % Convertir bloque a valor decimal (base 3)
    val = 0;
    for j = 1:block_size
      val = val + block(j) * 3^(block_size - j);
    end
    % Residuo mod-33
    residues(i) = mod(val, 33);
  end

  % Detectar ciclos: buscar repeticiones de residuos
  unique_residues = unique(residues);
  cycle_count = 0;
  cycle_info = {};

  for r = 1:length(unique_residues)
    positions = find(residues == unique_residues(r));
    if length(positions) >= 2
      % Calcular distancia entre apariciones
      diffs = diff(positions);
      if all(diffs == diffs(1)) && diffs(1) > 0
        % Ciclo regular detectado
        cycle_count = cycle_count + 1;
        cycle_info{cycle_count}.residue = unique_residues(r);
        cycle_info{cycle_count}.period = diffs(1);
        cycle_info{cycle_count}.occurrences = length(positions);
      end
    end
  end

  % Run-length encoding ternario sobre residuos
  compressed_residues = [];
  i = 1;
  while i <= length(residues)
    current = residues(i);
    count = 1;
    while i + count <= length(residues) && residues(i + count) == current
      count = count + 1;
    end
    % Codificar: [residuo, conteo] usando ternario
    compressed_residues = [compressed_residues, current, count];
    i = i + count;
  end

  % Ratio de compresión
  original_bits = n_trits * log2(3);
  compressed_bits = length(compressed_residues) * log2(33);
  compression_ratio = compressed_bits / original_bits;

  result.compressed = compressed_residues;
  result.residues = residues;
  result.cycles_detected = cycle_count;
  result.cycle_info = cycle_info;
  result.compression_ratio = compression_ratio;
  result.n_blocks = n_blocks;
  result.block_size = block_size;

end

function result = quipu_checksum(data_trits, mode)
% QUIPU_CHECKSUM  Checksum redundante inspirado en quipu inca
%   result = quipu_checksum(data_trits, 'encode') — genera paridad
%   result = quipu_checksum(codeword, 'decode') — verifica integridad
%
%   Inspiración: quipu — nudos grandes (+1), pequeños (-1), sin nudo (0)
%   Método: paridad ternaria por posición (GF(3))
%
%   Para cada bloque de 5 trits, se generan 2 trits de paridad:
%   p1 = -(d1 + d2 + d3) mod 3 (balanceado)
%   p2 = -(d1 + d2*d3) mod 3 (producto cruz)

  if nargin < 2
    mode = 'encode';
  end

  % Función para balancear trits: 0,1,2 → -1,0,+1
  function balanced = balance_trits(raw)
    balanced = raw;
    balanced(raw == 2) = -1;
  end

  % Función para mapear a {0,1,2}
  function raw = unbalance_trits(balanced)
    raw = balanced;
    raw(balanced == -1) = 2;
  end

  if strcmp(mode, 'encode')
    % Codificar: generar checksum
    n = length(data_trits);
    block_size = 5;
    n_blocks = floor(n / block_size);

    checksum = [];
    for b = 1:n_blocks
      block = data_trits((b-1)*block_size + 1 : b*block_size);
      % Paridad aditiva: p1 = -(d1+d2+d3+d4+d5) mod 3
      p1_raw = mod(-sum(unbalance_trits(block)), 3);
      % Paridad multiplicativa: p2 = -(d1*d2*d3*d4*d5) mod 3
      prod = 1;
      for i = 1:block_size
        prod = prod * unbalance_trits(block(i));
      end
      p2_raw = mod(-prod, 3);

      checksum = [checksum, balance_trits(p1_raw), balance_trits(p2_raw)];
    end

    result.codeword = [data_trits, checksum];
    result.checksum = checksum;
    result.n_data = n;
    result.n_checksum = length(checksum);
    result.block_size = block_size;
    result.n_blocks = n_blocks;

  elseif strcmp(mode, 'decode')
    % Decodificar: verificar integridad
    n = length(data_trits);
    block_size = 5;
    total_per_block = block_size + 2;
    n_blocks = floor(n / total_per_block);

    errors = [];
    syndromes = [];

    for b = 1:n_blocks
      start = (b-1) * total_per_block + 1;
      block = data_trits(start : start + block_size - 1);
      parity = data_trits(start + block_size : start + block_size + 1);

      % Recalcular paridad
      p1_raw = mod(-sum(unbalance_trits(block)), 3);
      prod = 1;
      for i = 1:block_size
        prod = prod * unbalance_trits(block(i));
      end
      p2_raw = mod(-prod, 3);

      % Syndrome
      s1 = mod(unbalance_trits(parity(1)) - p1_raw, 3);
      s2 = mod(unbalance_trits(parity(2)) - p2_raw, 3);

      syndromes = [syndromes; s1, s2];
      if s1 ~= 0 || s2 ~= 0
        errors = [errors, b];
      end
    end

    result.valid = isempty(errors);
    result.errors = errors;
    result.syndromes = syndromes;
    result.n_blocks = n_blocks;
    result.block_size = block_size;

  else
    error('Modo desconocido: use encode o decode');
  end

end

function result = benchmark(temperature_data)
% BENCHMARK  Comparación de métodos de compresión para sensores
%   result = benchmark(temperature_data) — compara ternario vs binario vs gzip
%
%   Métodos comparados:
%   1. Binario estándar (8 bits por valor, 0-255)
%   2. Ternario ancestral (trits + residual mod-33)
%   3. Ternario + quipu checksum
%   4. Delta encoding + binario
%   5. gzip sobre binario

  n = length(temperature_data);

  % --- Método 1: Binario estándar (8 bits por valor) ---
  binary_bits = n * 8;
  binary_bytes = ceil(binary_bits / 8);

  % --- Método 2: Ternario ancestral ---
  trits = ternary_codec(temperature_data, 'encode');
  ternary_result = residual_compressor(trits.trits);
  ternary_bits = length(ternary_result.compressed) * log2(33);

  % --- Método 3: Ternario + quipu checksum ---
  block_size = 5;
  n_blocks = floor(length(trits.trits) / block_size);
  if n_blocks > 0
    data_for_checksum = trits.trits(1:n_blocks * block_size);
    quipu_result = quipu_checksum(data_for_checksum, 'encode');
    ternary_quipu_bits = length(quipu_result.codeword) * log2(3);
  else
    ternary_quipu_bits = ternary_bits;
  end

  % --- Método 4: Delta encoding ---
  delta = diff(temperature_data);
  delta_bits = length(delta) * 8;  % cada diferencia en 8 bits

  % --- Método 5: gzip ---
  try
    % Simular gzip: comprimir datos binarios
    temp_file = [tempname, '.bin'];
    fid = fopen(temp_file, 'wb');
    fwrite(fid, uint8(temperature_data), 'uint8');
    fclose(fid);
    gzip(temp_file);
    gz_file = [temp_file, '.gz'];
    gz_info = dir(gz_file);
    gzip_bytes = gz_info.bytes;
    gzip_bits = gzip_bytes * 8;
    delete(gz_file);
    delete(temp_file);
  catch
    % Si gzip no disponible, estimar ratio típico ~0.6
    gzip_bits = binary_bits * 0.6;
  end

  % --- Resultados ---
  result.methods = {
    'Binario (8-bit)', binary_bits, binary_bits / binary_bits;
    'Ternario (residual)', ternary_bits, ternary_bits / binary_bits;
    'Ternario+Quipu', ternary_quipu_bits, ternary_quipu_bits / binary_bits;
    'Delta encoding', delta_bits, delta_bits / binary_bits;
    'gzip', gzip_bits, gzip_bits / binary_bits;
  };

  result.binary_bits = binary_bits;
  result.ternary_bits = ternary_bits;
  result.ternary_quipu_bits = ternary_quipu_bits;
  result.delta_bits = delta_bits;
  result.gzip_bits = gzip_bits;

  % Eficiencia energética (Landauer)
  kB = 1.380649e-23;  % J/K
  T = 300;            % K (temperatura ambiente)
  result.energy_binary = binary_bits * kB * T * log(2);
  result.energy_ternary = ternary_bits * kB * T * log(3);
  result.energy_saving = 1 - (result.energy_ternary / result.energy_binary);

  % Métricas adicionales
  result.n_samples = n;
  result.compression_ratio_ternary = ternary_bits / binary_bits;
  result.compression_ratio_gzip = gzip_bits / binary_bits;

end

% run_all.m  —  Motor Ternario Ancestral para Sensores IoT
% Ejecuta todo el pipeline: codec → compresión → checksum → benchmark
% Modo: MEDIDO (resultados reales de ejecución)

fprintf('=== MOTOR TERNARIO ANCESTRAL PARA SENSORES IoT ===\n');
fprintf('Fecha: %s\n\n', datestr(now));

% --- 1. Generar datos sintéticos de sensores ---
fprintf('--- 1. Generando datos de sensores ---\n');
n_samples = 1006;  % 7 días × 144 lecturas/día (cada 10 min)
t = (0:n_samples-1) * (10/1440);  % días
% Temperatura: ciclo diario ± 5°C, ruido gaussiano
temp_base = 25 + 5 * sin(2 * pi * t);  % ciclo diario
rng(42);  % semilla fija para reproducibilidad
noise = 0.5 * randn(1, n_samples);
temperature = temp_base + noise;
temperature = max(15, min(35, temperature));  % clamp 15-35°C

fprintf('  Muestras: %d, Rango: [%.1f, %.1f] °C\n', n_samples, min(temperature), max(temperature));

% --- 2. Codificación ternaria ---
fprintf('\n--- 2. Codificando en ternario ---\n');
trits_result = ternary_codec(temperature, 'encode');
fprintf('  Trits generados: %d\n', trits_result.n_trits);
fprintf('  Valor decimal (primera porción): %d\n', trits_result.decimal);

% Verificar: contar distribución de trits
n_cold = sum(trits_result.trits == -1);
n_normal = sum(trits_result.trits == 0);
n_hot = sum(trits_result.trits == 1);
fprintf('  Distribución: frío=%d, normal=%d, caliente=%d\n', n_cold, n_normal, n_hot);

% --- 3. Compresión residual ---
fprintf('\n--- 3. Compresión por residuos mod-33 ---\n');
residual_result = residual_compressor(trits_result.trits, 4);
fprintf('  Bloques procesados: %d\n', residual_result.n_blocks);
fprintf('  Residuos únicos: %d\n', length(unique(residual_result.residues)));
fprintf('  Ciclos detectados: %d\n', residual_result.cycles_detected);
fprintf('  Ratio de compresión: %.3f\n', residual_result.compression_ratio);

if residual_result.cycles_detected > 0
  fprintf('  Ciclos encontrados:\n');
  for c = 1:length(residual_result.cycle_info)
    ci = residual_result.cycle_info{c};
    fprintf('    Residuo %d: periodo=%d, ocurrencias=%d\n', ...
      ci.residue, ci.period, ci.occurrences);
  end
end

% --- 4. Checksum quipu ---
fprintf('\n--- 4. Checksum tipo quipu ---\n');
block_size = 5;
n_blocks_checksum = floor(length(trits_result.trits) / block_size);
if n_blocks_checksum > 0
  data_for_checksum = trits_result.trits(1:n_blocks_checksum * block_size);
  quipu_result = quipu_checksum(data_for_checksum, 'encode');
  fprintf('  Bloques de paridad: %d\n', quipu_result.n_blocks);
  fprintf('  Trits de datos: %d\n', quipu_result.n_data);
  fprintf('  Trits de checksum: %d\n', quipu_result.n_checksum);
  fprintf('  Total codeword: %d trits\n', length(quipu_result.codeword));

  % Verificar checksum
  verify = quipu_checksum(quipu_result.codeword, 'decode');
  fprintf('  Verificación: %s\n', mat2str(verify.valid));
  fprintf('  Errores detectados: %d\n', length(verify.errors));
end

% --- 5. Benchmark ---
fprintf('\n--- 5. Benchmark: comparación de métodos ---\n');
bench = benchmark(temperature);

fprintf('  Método                 | Bits   | Ratio  | Energía (J)\n');
fprintf('  -----------------------|--------|--------|------------\n');
for i = 1:size(bench.methods, 1)
  fprintf('  %-22s | %6d | %.3f  | %e\n', ...
    bench.methods{i,1}, bench.methods{i,2}, bench.methods{i,3}, ...
    bench.methods{i,2} * 1.380649e-23 * 300 * log(2));
end

fprintf('\n  Energía ternario vs binario:\n');
fprintf('    Binario: %e J\n', bench.energy_binary);
fprintf('    Ternario: %e J\n', bench.energy_ternary);
fprintf('    Ahorro: %.1f%%\n', bench.energy_saving * 100);

% --- 6. Verificación H4 (Landauer) ---
fprintf('\n--- 6. Verificación Landauer (H4) ---\n');
kB = 1.380649e-23;
T = 300;
E_binary = kB * T * log(2);
E_ternary = kB * T * log(3);
fprintf('  Energía por bit (binario): %e J\n', E_binary);
fprintf('  Energía por trit (ternario): %e J\n', E_ternary);
fprintf('  Eficiencia ternario/binario: %.3f\n', log(3)/log(2));
fprintf('  ln(3)/3 = %.6f vs ln(2)/2 = %.6f\n', log(3)/3, log(2)/2);
fprintf('  Ternario es %.1f%% más eficiente por símbolo\n', (log(3)/3 - log(2)/2) / (log(2)/2) * 100);

% --- 7. Guardar resultados ---
fprintf('\n--- 7. Guardando resultados ---\n');
results.mode = 'measured';
results.date = datestr(now);
results.n_samples = n_samples;
results.temperature_range = [min(temperature), max(temperature)];
results.ternary.n_trits = trits_result.n_trits;
results.ternary.distribution = [n_cold, n_normal, n_hot];
results.ternary.decimal = trits_result.decimal;
results.residual.n_blocks = residual_result.n_blocks;
results.residual.cycles_detected = residual_result.cycles_detected;
results.residual.compression_ratio = residual_result.compression_ratio;
results.residual.unique_residues = length(unique(residual_result.residues));
results.quipu.n_blocks = n_blocks_checksum;
results.quipu.total_codeword = length(quipu_result.codeword);
results.quipu.valid = verify.valid;
results.benchmark.binary_bits = bench.binary_bits;
results.benchmark.ternary_bits = bench.ternary_bits;
results.benchmark.ternary_quipu_bits = bench.ternary_quipu_bits;
results.benchmark.delta_bits = bench.delta_bits;
results.benchmark.gzip_bits = bench.gzip_bits;
results.benchmark.energy_binary = bench.energy_binary;
results.benchmark.energy_ternary = bench.energy_ternary;
results.benchmark.energy_saving_pct = bench.energy_saving * 100;
results.landauer.E_binary = E_binary;
results.landauer.E_ternary = E_ternary;
results.landauer.efficiency_ratio = log(3)/log(2);
results.landauer.ln3_over_3 = log(3)/3;
results.landauer.ln2_over_2 = log(2)/2;
results.landauer.advantage_pct = (log(3)/3 - log(2)/2) / (log(2)/2) * 100;

% Guardar JSON
fid = fopen('results.json', 'w');
fprintf(fid, '{\n');
fprintf(fid, '  "mode": "measured",\n');
fprintf(fid, '  "date": "%s",\n', datestr(now));
fprintf(fid, '  "n_samples": %d,\n', n_samples);
fprintf(fid, '  "temperature_range": [%.2f, %.2f],\n', min(temperature), max(temperature));
fprintf(fid, '  "ternary": {\n');
fprintf(fid, '    "n_trits": %d,\n', trits_result.n_trits);
fprintf(fid, '    "distribution": [%d, %d, %d],\n', n_cold, n_normal, n_hot);
fprintf(fid, '    "decimal": %d\n', trits_result.decimal);
